public class ApiDataProvider<T> : IDataTableDataProvider<T>
{
    private readonly IApiClient _api;
    private readonly string _endpoint;

    public ApiDataProvider(IApiClient api, string endpoint)
    {
        _api = api;
        _endpoint = endpoint;
    }

    public async Task<PagedResult<T>> GetDataAsync(
        DataTableQuery query, CancellationToken ct = default)
    {
        return await _api.GetPagedAsync<T>(_endpoint, query, ct);
    }
}
